def oracle(input):
    reserved = input['reserved']
    lines = input['lines']

    reserved_set = {}
    for t in reserved:
        reserved_set[t] = True

    def is_space(ch):
        return ch == ' '

    def is_digit(ch):
        return '0' <= ch <= '9'

    def is_word_char(ch):
        return ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ('0' <= ch <= '9') or ch == '_' or ch == '$'

    def is_word_start(ch):
        return ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ch == '_' or ch == '$'

    def parse_line(line):
        p = 0
        n = len(line)
        out = []
        while p < n:
            while p < n and line[p] == ' ':
                p += 1
            if p >= n:
                break
            if line[p] == '#':
                break

            best = None
            best_len = -1
            i = 0
            while i < len(reserved):
                tok = reserved[i]
                L = len(tok)
                if p + L <= n and line[p:p+L] == tok:
                    if L > best_len:
                        best = tok
                        best_len = L
                i += 1

            num_len = 0
            if is_digit(line[p]):
                q = p
                while q < n and is_digit(line[q]):
                    q += 1
                num_len = q - p
                cand = line[p:q]
                if cand in reserved_set and num_len > best_len:
                    best = cand
                    best_len = num_len

            word_len = 0
            if is_word_start(line[p]):
                q = p
                while q < n and is_word_char(line[q]):
                    q += 1
                word_len = q - p
                cand = line[p:q]
                if cand in reserved_set and word_len > best_len:
                    best = cand
                    best_len = word_len

            if best is not None:
                out.append(['R', best])
                p += best_len
            elif num_len > 0:
                out.append(['N', line[p:p+num_len]])
                p += num_len
            elif word_len > 0:
                out.append(['W', line[p:p+word_len]])
                p += word_len
            else:
                out.append(['R', line[p]])
                p += 1
        return out

    tokens = []
    li = 0
    while li < len(lines):
        part = parse_line(lines[li])
        j = 0
        while j < len(part):
            tokens.append(part[j])
            j += 1
