            if not ('0' <= s[i] <= '9'):
                all_digits = False
                break
            i += 1
        if all_digits:
            return 'N'
        first = s[0]
        if ('a' <= first <= 'z') or ('A' <= first <= 'Z') or first == '_' or first == '$':
            ok = True
            i = 1
            while i < len(s):
                c = s[i]
                if not (('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9') or c == '_' or c == '$'):
                    ok = False
                    break
                i += 1
            if ok:
                if s in reserved_set:
                    return 'RWORD'
                return 'W'
        return 'R'

    def needs_space(a, b):
