        s2 = token_text(b)
        c1 = token_kind_text(s1)
        c2 = token_kind_text(s2)
        if (c1 == 'W' or c1 == 'N' or c1 == 'RWORD') and (c2 == 'W' or c2 == 'N' or c2 == 'RWORD'):
