def oracle(input):
    nums = input['nums']
    k = input['k']
    n = len(nums)
    m = n // 2
    pairs = []
    for i in range(m):
        a = nums[i]
        b = nums[n - 1 - i]
        if a > b:
            a, b = b, a
        d = b - a
        t = b
        if k - a > t:
            t = k - a
        pairs.append((d, t))
    diff_count = {}
    threshold_count = {}
    for d, t in pairs:
        if d in diff_count:
            diff_count[d] += 1
        else:
            diff_count[d] = 1
        if t in threshold_count:
            threshold_count[t] += 1
        else:
            threshold_count[t] = 1
    keys = {}
    keys[0] = 1
    keys[k] = 1
    for d, t in pairs:
        keys[d] = 1
        keys[t] = 1
    sorted_thresholds = sorted(threshold_count)
    prefix = []
    running = 0
    for x in sorted_thresholds:
        running += threshold_count[x]
        prefix.append(running)
    def count_leq(x):
        lo = 0
        hi = len(sorted_thresholds)
        while lo < hi:
            mid = (lo + hi) // 2
            if sorted_thresholds[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        if lo == 0:
            return 0
        return prefix[lo - 1]
    ans = None
    for x in keys:
        one_change_possible = count_leq(x)
        two_changes_needed = m - one_change_possible
        zero_changes = diff_count.get(x, 0)
        cost = 2 * two_changes_needed + (one_change_possible - zero_changes)
        if ans is None or cost < ans:
            ans = cost
    return ans

